/**
 * TOML parser and formatter
 * Takes exactly one argument: 'json' or 'keys'
 * Reads TOML from stdin and outputs JSON or key listing
 */

import { readFileSync } from 'fs'

// Check arguments
if (process.argv.length !== 3 || !['json', 'keys'].includes(process.argv[2])) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const mode = process.argv[2]

// Read stdin
let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch (e) {
  process.stderr.write('error: failed to read stdin\n')
  process.exit(2)
}

// Split into lines and drop empty tail from trailing newline
const lines = input.split('\n')
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop()
}

try {
  const doc = parseToml(lines)

  if (mode === 'json') {
    process.stdout.write(toJson(doc))
  } else if (mode === 'keys') {
    process.stdout.write(toKeys(doc))
  }
  process.exit(0)
} catch (err) {
  process.stderr.write(err.message + '\n')
  process.exit(2)
}

function parseToml(lines) {
  const root = {}
  let currentTable = root
  const tableStack = [{ table: root, path: [] }]
  const definedTables = new Set()
  const definedKeys = new Set()

  definedTables.add('')

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum]
    const lineNumber = lineNum + 1

    // Remove comments (but not in strings)
    const trimmedLine = removeLine(line)

    // Skip empty lines and comments
    if (trimmedLine === '') {
      continue
    }

    // Check if it's a table header
    if (trimmedLine.startsWith('[')) {
      const result = parseTableHeader(trimmedLine, lineNumber)
      const { isArrayTable, path, trailingText } = result

      if (trailingText) {
        throw new ParseError(lineNumber, 'trailing text after a table header')
      }

      const pathStr = path.join('.')

      if (isArrayTable) {
        // [[name]] - array of tables
        setTableArray(root, path, tableStack, definedTables, definedKeys, lineNumber)
        currentTable = tableStack[tableStack.length - 1].table
      } else {
        // [name] - table
        if (definedTables.has(pathStr)) {
          throw new ParseError(lineNumber, `table ${pathStr} is defined twice`)
        }
        setTable(root, path, tableStack, definedTables, lineNumber)
        currentTable = tableStack[tableStack.length - 1].table
        definedTables.add(pathStr)
      }
    } else {
      // Key-value pair
      const result = parseKeyValue(trimmedLine, lineNumber)
      const { keys, value, trailingText } = result

      if (trailingText) {
        throw new ParseError(lineNumber, 'trailing text after a value')
      }

      // Check for duplicate keys
      const keyPath = keys.join('.')
      const fullPath = [...tableStack[tableStack.length - 1].path, ...keys].join('.')

      if (definedKeys.has(fullPath)) {
        throw new ParseError(lineNumber, `key ${fullPath} is defined twice`)
      }
      definedKeys.add(fullPath)

      // Set the value in the current table
      setNestedValue(currentTable, keys, value, definedTables, definedKeys, lineNumber)
    }
  }

  return root
}

function removeLine(line) {
  // Remove leading whitespace
  let i = 0
  while (i < line.length && (line[i] === ' ' || line[i] === '\t')) {
    i++
  }

  // Check if line is a comment or empty
  if (i === line.length) {
    return ''
  }
  if (line[i] === '#' || line[i] === ';') {
    return ''
  }

  // Find the end of the line (before comment)
  let j = line.length
  let inString = false
  let stringChar = null

  for (let k = 0; k < line.length; k++) {
    const char = line[k]

    if (!inString) {
      if (char === '"' || char === "'") {
        inString = true
        stringChar = char
      } else if ((char === '#' || char === ';') && k > 0) {
        // Check if there's whitespace before the comment
        j = k
        break
      }
    } else {
      if (char === stringChar && (k === 0 || line[k - 1] !== '\\')) {
        inString = false
      }
    }
  }

  return line.substring(0, j).trimEnd()
}

function parseTableHeader(line, lineNumber) {
  if (line[0] !== '[') {
    throw new ParseError(lineNumber, 'expected key = value')
  }

  let isArrayTable = false
  let pos = 1

  if (line[1] === '[') {
    isArrayTable = true
    pos = 2
  }

  // Parse the table name
  const { names, pos: newPos } = parseDottedName(line, pos, lineNumber)
  pos = newPos

  // Skip whitespace
  while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) {
    pos++
  }

  // Check for closing bracket(s)
  if (isArrayTable) {
    if (pos >= line.length || line[pos] !== ']' || pos + 1 >= line.length || line[pos + 1] !== ']') {
      throw new ParseError(lineNumber, 'unterminated table header')
    }
    pos += 2
  } else {
    if (pos >= line.length || line[pos] !== ']') {
      throw new ParseError(lineNumber, 'unterminated table header')
    }
    pos += 1
  }

  // Check for trailing text (comments are allowed)
  let trailingText = ''
  while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) {
    pos++
  }
  if (pos < line.length && line[pos] !== '#' && line[pos] !== ';') {
    trailingText = line.substring(pos)
  }

  return {
    isArrayTable,
    path: names,
    trailingText
  }
}

function parseDottedName(line, startPos, lineNumber) {
  const names = []
  let pos = startPos

  while (pos < line.length) {
    // Skip whitespace
    while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) {
      pos++
    }

    // Parse name
    let name = ''
    if (pos < line.length && line[pos] === '"') {
      // Quoted name
      pos++
      while (pos < line.length && line[pos] !== '"') {
        if (line[pos] === '\\') {
          pos++
          if (pos >= line.length) {
            throw new ParseError(lineNumber, 'unterminated string')
          }
          const nextChar = line[pos]
          if (nextChar === '"' || nextChar === '\\' || nextChar === 'n' || nextChar === 't' || nextChar === 'r' || nextChar === '0' || nextChar === 'u') {
            name += line[pos]
          } else {
            throw new ParseError(lineNumber, `invalid escape \\${nextChar}`)
          }
          pos++
        } else {
          name += line[pos]
          pos++
        }
      }
      if (pos >= line.length) {
        throw new ParseError(lineNumber, 'unterminated string')
      }
      pos++
    } else if (pos < line.length && line[pos] === "'") {
      // Literal string (quoted name)
      pos++
      while (pos < line.length && line[pos] !== "'") {
        name += line[pos]
        pos++
      }
      if (pos >= line.length) {
        throw new ParseError(lineNumber, 'unterminated string')
      }
      pos++
    } else {
      // Bare word
      if (pos >= line.length || !isNameChar(line[pos])) {
        throw new ParseError(lineNumber, 'expected a name')
      }
      while (pos < line.length && isNameChar(line[pos])) {
        name += line[pos]
        pos++
      }
    }

    if (name === '') {
      throw new ParseError(lineNumber, 'expected a name')
    }
    names.push(name)

    // Skip whitespace
    while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) {
      pos++
    }

    // Check for dot
    if (pos < line.length && line[pos] === '.') {
      pos++
    } else {
      break
    }
  }

  return { names, pos }
}

function parseKeyValue(line, lineNumber) {
  // Parse key
  const { names, pos: afterKey } = parseDottedName(line, 0, lineNumber)

  let pos = afterKey

  // Skip whitespace
  while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) {
    pos++
  }

  // Expect =
  if (pos >= line.length || line[pos] !== '=') {
    throw new ParseError(lineNumber, 'expected key = value')
  }
  pos++

  // Skip whitespace
  while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) {
    pos++
  }

  // Parse value
  const { value, pos: afterValue } = parseValue(line, pos, lineNumber)

  let pos2 = afterValue

  // Check for trailing text (comments are allowed)
  let trailingText = ''
  while (pos2 < line.length && (line[pos2] === ' ' || line[pos2] === '\t')) {
    pos2++
  }
  if (pos2 < line.length && line[pos2] !== '#' && line[pos2] !== ';') {
    trailingText = line.substring(pos2)
  }

  return {
    keys: names,
    value,
    trailingText
  }
}

function parseValue(line, startPos, lineNumber) {
  let pos = startPos

  // Skip whitespace
  while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) {
    pos++
  }

  if (pos >= line.length) {
    throw new ParseError(lineNumber, 'expected a value')
  }

  const char = line[pos]

  // Boolean
  if (line.substring(pos, pos + 4) === 'true') {
    return { value: true, pos: pos + 4 }
  }
  if (line.substring(pos, pos + 5) === 'false') {
    return { value: false, pos: pos + 5 }
  }

  // String
  if (char === '"') {
    return parseBasicString(line, pos, lineNumber)
  }
  if (char === "'") {
    return parseLiteralString(line, pos, lineNumber)
  }

  // Array
  if (char === '[') {
    return parseArray(line, pos, lineNumber)
  }

  // Inline table
  if (char === '{') {
    return parseInlineTable(line, pos, lineNumber)
  }

  // Number or bare word
  return parseNumber(line, pos, lineNumber)
}

function parseBasicString(line, startPos, lineNumber) {
  let pos = startPos + 1
  let str = ''

  while (pos < line.length) {
    const char = line[pos]

    if (char === '"') {
      return { value: str, pos: pos + 1 }
    }

    if (char === '\\') {
      pos++
      if (pos >= line.length) {
        throw new ParseError(lineNumber, 'unterminated string')
      }
      const nextChar = line[pos]
      if (nextChar === '"') {
        str += '"'
      } else if (nextChar === '\\') {
        str += '\\'
      } else if (nextChar === 'n') {
        str += '\n'
      } else if (nextChar === 't') {
        str += '\t'
      } else if (nextChar === 'r') {
        str += '\r'
      } else if (nextChar === '0') {
        str += '\0'
      } else if (nextChar === 'u') {
        if (pos + 4 >= line.length) {
          throw new ParseError(lineNumber, 'invalid escape \\u')
        }
        const hex = line.substring(pos + 1, pos + 5)
        if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
          throw new ParseError(lineNumber, `invalid escape \\u${hex}`)
        }
        str += String.fromCharCode(parseInt(hex, 16))
        pos += 4
      } else {
        throw new ParseError(lineNumber, `invalid escape \\${nextChar}`)
      }
      pos++
    } else {
      str += char
      pos++
    }
  }

  throw new ParseError(lineNumber, 'unterminated string')
}

function parseLiteralString(line, startPos, lineNumber) {
  let pos = startPos + 1
  let str = ''

  while (pos < line.length) {
    const char = line[pos]

    if (char === "'") {
      return { value: str, pos: pos + 1 }
    }

    str += char
    pos++
  }

  throw new ParseError(lineNumber, 'unterminated string')
}

function parseArray(line, startPos, lineNumber) {
  let pos = startPos + 1
  const arr = []

  while (pos < line.length) {
    // Skip whitespace
    while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) {
      pos++
    }

    // Check for end of array
    if (pos < line.length && line[pos] === ']') {
      return { value: arr, pos: pos + 1 }
    }

    // Check for comment
    if (pos < line.length && (line[pos] === '#' || line[pos] === ';')) {
      break
    }

    // Check for comma
    if (pos < line.length && line[pos] === ',') {
      pos++
      continue
    }

    // Parse value
    const { value, pos: afterValue } = parseValue(line, pos, lineNumber)
    arr.push(value)
    pos = afterValue

    // Skip whitespace
    while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) {
      pos++
    }

    // Check for comma or end
    if (pos < line.length && line[pos] === ',') {
      pos++
    } else if (pos < line.length && line[pos] === ']') {
      continue
    } else if (pos >= line.length || line[pos] === '#' || line[pos] === ';') {
      break
    }
  }

  throw new ParseError(lineNumber, 'unterminated array')
}

function parseInlineTable(line, startPos, lineNumber) {
  let pos = startPos + 1
  const obj = {}

  while (pos < line.length) {
    // Skip whitespace
    while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) {
      pos++
    }

    // Check for end of table
    if (pos < line.length && line[pos] === '}') {
      return { value: obj, pos: pos + 1 }
    }

    // Parse key
    const { names, pos: afterKey } = parseDottedName(line, pos, lineNumber)
    pos = afterKey

    // Skip whitespace
    while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) {
      pos++
    }

    // Expect =
    if (pos >= line.length || line[pos] !== '=') {
      throw new ParseError(lineNumber, 'expected = in an inline table')
    }
    pos++

    // Skip whitespace
    while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) {
      pos++
    }

    // Parse value
    const { value, pos: afterValue } = parseValue(line, pos, lineNumber)

    // Set value in object
    setNestedValueInline(obj, names, value)

    pos = afterValue

    // Skip whitespace
    while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) {
      pos++
    }

    // Check for comma or end
    if (pos < line.length && line[pos] === ',') {
      pos++
    } else if (pos < line.length && line[pos] === '}') {
      continue
    } else if (pos < line.length) {
      throw new ParseError(lineNumber, 'expected = in an inline table')
    }
  }

  throw new ParseError(lineNumber, 'unterminated inline table')
}

function parseNumber(line, startPos, lineNumber) {
  let pos = startPos
  let numStr = ''

  // Optional sign
  if (pos < line.length && (line[pos] === '+' || line[pos] === '-')) {
    numStr += line[pos]
    pos++
  }

  // Integer part
  if (pos >= line.length || !isDigit(line[pos])) {
    throw new ParseError(lineNumber, `invalid value ${line.substring(startPos, Math.min(startPos + 20, line.length))}`)
  }

  while (pos < line.length && (isDigit(line[pos]) || line[pos] === '_')) {
    if (line[pos] !== '_') {
      numStr += line[pos]
    }
    pos++
  }

  // Check for float (fraction or exponent)
  if (pos < line.length && line[pos] === '.') {
    numStr += '.'
    pos++
    if (pos >= line.length || !isDigit(line[pos])) {
      throw new ParseError(lineNumber, `invalid value ${line.substring(startPos, Math.min(startPos + 20, line.length))}`)
    }
    while (pos < line.length && (isDigit(line[pos]) || line[pos] === '_')) {
      if (line[pos] !== '_') {
        numStr += line[pos]
      }
      pos++
    }
  }

  // Check for exponent
  if (pos < line.length && (line[pos] === 'e' || line[pos] === 'E')) {
    numStr += 'e'
    pos++
    if (pos < line.length && (line[pos] === '+' || line[pos] === '-')) {
      numStr += line[pos]
      pos++
    }
    if (pos >= line.length || !isDigit(line[pos])) {
      throw new ParseError(lineNumber, `invalid value ${line.substring(startPos, Math.min(startPos + 20, line.length))}`)
    }
    while (pos < line.length && (isDigit(line[pos]) || line[pos] === '_')) {
      if (line[pos] !== '_') {
        numStr += line[pos]
      }
      pos++
    }
  }

  // Parse number
  if (numStr.includes('.') || numStr.includes('e') || numStr.includes('E')) {
    return { value: parseFloat(numStr), pos }
  } else {
    return { value: parseInt(numStr, 10), pos }
  }
}

function isNameChar(char) {
  return /[A-Za-z0-9_-]/.test(char)
}

function isDigit(char) {
  return /[0-9]/.test(char)
}

function setTable(root, path, tableStack, definedTables, lineNumber) {
  let current = root
  const newStack = [{ table: root, path: [] }]

  for (let i = 0; i < path.length; i++) {
    const key = path[i]
    const currentPath = path.slice(0, i + 1).join('.')

    if (!current[key]) {
      current[key] = {}
    } else if (typeof current[key] !== 'object' || Array.isArray(current[key])) {
      throw new ParseError(lineNumber, `${currentPath} is not a table`)
    }

    current = current[key]
    newStack.push({ table: current, path: path.slice(0, i + 1) })
  }

  tableStack.length = 1
  for (const entry of newStack) {
    tableStack.push(entry)
  }
}

function setTableArray(root, path, tableStack, definedTables, definedKeys, lineNumber) {
  let current = root

  for (let i = 0; i < path.length - 1; i++) {
    const key = path[i]
    const currentPath = path.slice(0, i + 1).join('.')

    if (!current[key]) {
      current[key] = {}
    } else if (typeof current[key] !== 'object' || Array.isArray(current[key])) {
      throw new ParseError(lineNumber, `${currentPath} is not a table`)
    }

    current = current[key]
  }

  const lastKey = path[path.length - 1]
  const lastPath = path.join('.')

  if (!current[lastKey]) {
    current[lastKey] = []
  } else if (!Array.isArray(current[lastKey])) {
    throw new ParseError(lineNumber, `${lastPath} is not an array of tables`)
  }

  const newTable = {}
  current[lastKey].push(newTable)

  tableStack.length = 1
  let temp = root
  for (let i = 0; i < path.length - 1; i++) {
    temp = temp[path[i]]
    tableStack.push({ table: temp, path: path.slice(0, i + 1) })
  }
  tableStack.push({ table: newTable, path })
}

function setNestedValue(table, keys, value, definedTables, definedKeys, lineNumber) {
  let current = table

  for (let i = 0; i < keys.length - 1; i++) {
    const key = keys[i]
    const currentPath = keys.slice(0, i + 1).join('.')

    if (!current[key]) {
      current[key] = {}
    } else if (typeof current[key] !== 'object' || Array.isArray(current[key])) {
      throw new ParseError(lineNumber, `${currentPath} is not a table`)
    }

    current = current[key]
  }

  const lastKey = keys[keys.length - 1]
  if (current[lastKey] !== undefined) {
    throw new ParseError(lineNumber, `key ${keys.join('.')} is defined twice`)
  }

  current[lastKey] = value
}

function setNestedValueInline(obj, keys, value) {
  let current = obj

  for (let i = 0; i < keys.length - 1; i++) {
    const key = keys[i]

    if (!current[key]) {
      current[key] = {}
    }

    current = current[key]
  }

  const lastKey = keys[keys.length - 1]
  current[lastKey] = value
}

function toJson(obj) {
  return JSON.stringify(obj, (key, value) => {
    if (Array.isArray(value)) {
      return value
    }
    if (value && typeof value === 'object') {
      const sorted = {}
      const keys = Object.keys(value).sort()
      for (const k of keys) {
        sorted[k] = value[k]
      }
      return sorted
    }
    return value
  }, 2) + '\n'
}

function toKeys(obj, prefix = '') {
  const lines = []
  const keys = Object.keys(obj).sort()

  for (const key of keys) {
    const value = obj[key]
    const path = prefix ? prefix + '.' + key : key

    if (Array.isArray(value) && value.length > 0 && typeof value[0] === 'object' && !Array.isArray(value[0])) {
      // Array of tables
      lines.push(path + ' array')
      for (let i = 0; i < value.length; i++) {
        const subLines = toKeys(value[i], path + '[' + i + ']')
        lines.push(...subLines.split('\n').filter(l => l))
      }
    } else if (Array.isArray(value)) {
      // Regular array
      lines.push(path + ' array')
      for (let i = 0; i < value.length; i++) {
        const item = value[i]
        if (typeof item === 'boolean') {
          lines.push(path + '[' + i + '] boolean')
        } else if (typeof item === 'number') {
          if (Number.isInteger(item)) {
            lines.push(path + '[' + i + '] integer')
          } else {
            lines.push(path + '[' + i + '] float')
          }
        } else if (typeof item === 'string') {
          lines.push(path + '[' + i + '] string')
        } else if (Array.isArray(item)) {
          lines.push(path + '[' + i + '] array')
        } else if (typeof item === 'object') {
          lines.push(path + '[' + i + '] table')
        }
      }
    } else if (typeof value === 'object' && value !== null) {
      // Table
      lines.push(path + ' table')
      const subLines = toKeys(value, path)
      lines.push(...subLines.split('\n').filter(l => l))
    } else if (typeof value === 'boolean') {
      lines.push(path + ' boolean')
    } else if (typeof value === 'number') {
      if (Number.isInteger(value)) {
        lines.push(path + ' integer')
      } else {
        lines.push(path + ' float')
      }
    } else if (typeof value === 'string') {
      lines.push(path + ' string')
    }
  }

  return lines.join('\n')
}

class ParseError extends Error {
  constructor(lineNumber, reason) {
    super(`error: line ${lineNumber}: ${reason}`)
    this.lineNumber = lineNumber
    this.reason = reason
  }
}
